import type { BankQuestion } from "@/lib/bank";

/** Simple Interest (Quantitative Aptitude): 143 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-simple-interest-1","question":"At what rate of simple interest will a sum double itself in 10 years?","options":["5%","8%","10%","12%"],"answer":2,"explanation":"To double, SI = P, so P = P × R × 10 / 100, giving R = 10%.","difficulty":"moderate"},
  {"id":"quant-simple-interest-2","question":"Amount at simple interest equals:","options":["Principal × Rate","Principal + Simple Interest","Principal − Simple Interest","Rate × Time"],"answer":1,"explanation":"Amount = Principal + SI.","difficulty":"easy"},
  {"id":"quant-simple-interest-3","question":"The simple interest on ₹1,000 at 5% per annum for 2 years is:","options":["₹50","₹100","₹150","₹200"],"answer":1,"explanation":"SI = 1000 × 5 × 2 ÷ 100 = ₹100.","difficulty":"easy"},
  {"id":"quant-simple-interest-4","question":"A sum becomes ₹1,200 in 2 years and ₹1,500 in 5 years at simple interest. The rate of interest is:","options":["5%","8%","10%","12%"],"answer":2,"explanation":"Interest for 3 years = 1,500 − 1,200 = ₹300, so ₹100 per year. Principal = 1,200 − 2 × 100 = ₹1,000; rate = 100 ÷ 1,000 × 100 = 10%.","difficulty":"hard"},
  {"id":"quant-simple-interest-5","question":"Simple interest on ₹5,000 at 8% per annum for 3 years is:","options":["₹1,000","₹1,200","₹1,500","₹2,400"],"answer":1,"explanation":"SI = 5000 × 8 × 3 / 100 = ₹1,200.","difficulty":"easy","source":"RRB Group D · SSC CHSL"},
  {"id":"quant-simple-interest-6","question":"A sum doubles itself in 8 years at simple interest. The rate per annum is:","options":["8%","10%","12.5%","16%"],"answer":2,"explanation":"SI = P in 8 years ⇒ R = 100/8 = 12.5%.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-simple-interest-7","question":"At simple interest a sum amounts to ₹6,500 in 3 years and ₹7,500 in 5 years. The sum is:","options":["₹4,500","₹5,000","₹5,500","₹6,000"],"answer":1,"explanation":"Two years’ interest = 1,000 ⇒ ₹500 per year ⇒ P = 6,500 − 1,500 = ₹5,000.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-simple-interest-8","question":"A sum at simple interest becomes 3 times itself in 20 years. In how many years will it become 5 times?","options":["30","35","40","50"],"answer":2,"explanation":"Interest of 2P in 20 years ⇒ P per 10 years; 4P needs 40 years.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk"},
  {"id":"quant-simple-interest-9","question":"The simple interest on ₹7,200 at 7.5% per annum for 8 months is:","options":["₹400","₹450","₹540","₹360"],"answer":3,"explanation":"8 months = 2/3 year. SI = 7,200 × 7.5/100 × 2/3 = ₹360. ₹540 is the interest for a full year.","difficulty":"easy","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-10","question":"What sum yields ₹600 as simple interest in 4 years at 5% per annum?","options":["₹3,000","₹2,500","₹2,400","₹3,600"],"answer":0,"explanation":"SI = P × 5 × 4/100 = 0.2P = 600, so P = ₹3,000.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-simple-interest-11","question":"At what rate per annum will the simple interest on a sum for 5 years be 2/5 of the principal?","options":["8%","5%","12.5%","10%"],"answer":0,"explanation":"r × 5/100 = 2/5, so r = 40/5 = 8% per annum.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-12","question":"₹9,200 is divided into two parts such that the simple interest on the first at 4% for 2 years equals the simple interest on the second at 5% for 3 years. The smaller part is:","options":["₹3,200","₹4,600","₹4,000","₹6,000"],"answer":0,"explanation":"8% of x = 15% of y, so x : y = 15 : 8. Total 23 units = 9,200, one unit = 400; the parts are ₹6,000 and ₹3,200. Smaller part = ₹3,200.","difficulty":"moderate","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-13","question":"The simple interest on a sum for 3 years at 5% per annum is ₹120 less than the simple interest on the same sum for 5 years at 4% per annum. The sum is:","options":["₹1,200","₹3,000","₹2,400","₹2,000"],"answer":2,"explanation":"Interest percentages are 15% and 20% of the sum; the difference 5% = ₹120, so the sum = ₹2,400.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-14","question":"A sum of ₹1,120 amounts to ₹1,344 in 4 years at simple interest. At the same rate it will amount to how much in 6 years?","options":["₹1,400","₹1,456","₹1,512","₹1,344"],"answer":1,"explanation":"SI for 4 years = 224, i.e. ₹56 a year. In 6 years SI = ₹336 and the amount = 1,120 + 336 = ₹1,456.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"quant-simple-interest-15","question":"A sum is lent at simple interest at 5% per annum for the first 2 years, 8% per annum for the next 3 years and 10% per annum beyond 5 years. If the interest for 8 years is ₹1,280, the sum is:","options":["₹2,500","₹2,000","₹1,800","₹1,600"],"answer":1,"explanation":"Total interest = (2 × 5 + 3 × 8 + 3 × 10)% = 64% of the sum = ₹1,280, so the sum = ₹2,000.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-16","question":"A lends ₹5,000 to B at 8% per annum simple interest, and B lends the same sum to C at 12.5% per annum. B's gain over 3 years is:","options":["₹1,125","₹600","₹675","₹750"],"answer":2,"explanation":"B's net rate = 12.5 − 8 = 4.5% a year, so gain = 5,000 × 4.5 × 3/100 = ₹675. ₹1,125 is the interest B earns from C before paying A.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-17","question":"At simple interest a sum becomes 1.16 times itself in as many years as the rate percent per annum. The rate is:","options":["2%","4%","16%","8%"],"answer":1,"explanation":"SI = 16% of P with r = t: r × r/100 = 0.16, r² = 16, r = 4% for 4 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-18","question":"What annual instalment will discharge a debt of ₹630 due in 3 years at 5% per annum simple interest?","options":["₹210","₹240","₹230","₹220"],"answer":2,"explanation":"The debt grows to 630 × 1.15 = ₹724.5 in 3 years. Instalment x paid at the end of years 1, 2, 3 earns SI for 2, 1, 0 years: x(1.10 + 1.05 + 1) = 3.15x = 724.5, so x = ₹230. ₹210 (630/3) ignores interest.","difficulty":"hard","source":"SSC CGL · CDS"},
  {"id":"quant-simple-interest-19","question":"A sum is lent at 6% per annum simple interest for 5 years, and the whole amount is then lent at 8% simple interest for 2 more years, finally amounting to ₹7,540. The original sum was:","options":["₹5,000","₹5,800","₹4,500","₹6,500"],"answer":0,"explanation":"After 5 years the amount is 1.30P; after 2 more years it is 1.30P × 1.16 = 1.508P = 7,540, so P = ₹5,000.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-20","question":"A man invests 1/3 of his capital at 3%, 1/4 at 4% and the rest at 6% simple interest. If his annual income from interest is ₹270, his capital is:","options":["₹6,000","₹6,500","₹7,200","₹5,400"],"answer":0,"explanation":"The rest = 1 − 1/3 − 1/4 = 5/12. Overall rate = 3/3 + 4/4 + 6 × 5/12 = 1 + 1 + 2.5 = 4.5%. Capital = 270/0.045 = ₹6,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-21","question":"₹12,000 is lent partly at 5% and partly at 8% per annum simple interest. If the total interest after 2 years is ₹1,500, the part lent at 8% is:","options":["₹6,000","₹4,000","₹7,000","₹5,000"],"answer":3,"explanation":"Let x be at 8%: 0.16x + 0.10(12,000 − x) = 1,500, so 0.06x = 300 and x = ₹5,000. Check: 800 + 700 = 1,500.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-22","question":"How many of the following statements about simple interest are correct?\n1. The interest earned in each year is the same.\n2. A sum doubles itself in 8 years at 12.5% per annum.\n3. If both the rate and the time are halved, the interest becomes half.\n4. The simple interest on ₹1,000 at 10% per annum for 6 months is ₹100.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"1 is true. 2 is true (12.5 × 8 = 100%). 3 is false: halving both makes the interest one-quarter. 4 is false: 6 months gives ₹50. Two statements are correct.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-simple-interest-23","question":"A sum amounts to ₹2,300 in 3 years at a certain rate of simple interest. Had the rate been 2 percentage points higher, it would have amounted to ₹2,420 in the same time. The sum is:","options":["₹2,200","₹2,100","₹1,800","₹2,000"],"answer":3,"explanation":"The extra interest = 2% × 3 years = 6% of the sum = 2,420 − 2,300 = ₹120, so the sum = ₹2,000 (and the original rate is 5%).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-24","question":"A debt of ₹848 due in 4 years at 4% per annum simple interest is to be discharged by 4 equal annual instalments. Each instalment is:","options":["₹240","₹250","₹212","₹232"],"answer":3,"explanation":"The debt becomes 848 × 1.16 = ₹983.68 after 4 years. Instalments earn interest for 3, 2, 1 and 0 years: x(1.12 + 1.08 + 1.04 + 1) = 4.24x = 983.68, so x = ₹232. ₹212 is just 848/4.","difficulty":"very-hard","source":"SSC CGL · CDS"},
  {"id":"quant-simple-interest-25","question":"The simple interest on a sum is 1/9 of the principal and the number of years equals the rate percent per annum. The rate is:","options":["9%","3%","3⅓%","2⅓%"],"answer":2,"explanation":"r × r/100 = 1/9, so r² = 100/9 and r = 10/3 = 3⅓% per annum (for 3⅓ years).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-26","question":"A sum lent at 6% per annum simple interest for a certain number of years earns ₹1,440. Had it been lent at 8% per annum for 2 years longer, it would have earned ₹2,560. The sum is:","options":["₹4,800","₹5,000","₹3,600","₹4,000"],"answer":3,"explanation":"6Pt/100 = 1,440 and 8P(t + 2)/100 = 2,560. Dividing: 8(t + 2)/(6t) = 16/9, so 72(t + 2) = 96t, t = 6 years, and P = 1,440 × 100/36 = ₹4,000.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-27","question":"Two sums in the ratio 3 : 5 are lent at 8% and 6% per annum simple interest respectively. If the total interest after 4 years is ₹1,296, the larger sum is:","options":["₹4,800","₹3,000","₹2,400","₹1,800"],"answer":1,"explanation":"Let the sums be 3x and 5x. Interest = 3x × 0.32 + 5x × 0.24 = 0.96x + 1.20x = 2.16x = 1,296, so x = 600 and the larger sum = ₹3,000.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-28","question":"The simple interest on ₹6,000 at 10% per annum from 4 February 2024 to 17 April 2024 (counting 1 year as 365 days and excluding the starting day) is:","options":["₹100","₹150","₹120","₹125"],"answer":2,"explanation":"Days: 25 in February (2024 is a leap year, 29 − 4), 31 in March and 17 in April = 73 days = 1/5 year. SI = 6,000 × 0.10 × 1/5 = ₹120.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-29", "question": "What is the simple interest on ₹2,500 at 6% per annum for 3 years?", "options": ["₹150", "₹450", "₹500", "₹375"], "answer": 1, "explanation": "SI = P × R × T / 100 = 2,500 × 6 × 3 / 100 = ₹450. ₹150 is only one year's interest.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "quant-simple-interest-30", "question": "In how many years will ₹4,000 amount to ₹5,200 at 7.5% per annum simple interest?", "options": ["4 years", "3 years", "5 years", "6 years"], "answer": 0, "explanation": "Interest needed = 1,200. One year's interest = 4,000 × 7.5% = 300. Time = 1,200 ÷ 300 = 4 years.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-simple-interest-31", "question": "A sum becomes three times itself in 25 years at simple interest. What is the rate per annum?", "options": ["12%", "4%", "10%", "8%"], "answer": 3, "explanation": "Tripling means interest = 2P (200% of P) in 25 years, so rate = 200/25 = 8%. 12% wrongly takes 300%.", "difficulty": "moderate", "source": "SSC CGL"},
  {"id": "quant-simple-interest-32", "question": "₹15,000 is lent partly at 8% and the rest at 12% per annum simple interest. The total interest after 3 years is ₹4,560. How much was lent at 12%?", "options": ["₹7,000", "₹7,500", "₹8,000", "₹9,000"], "answer": 2, "explanation": "Yearly interest = 4,560 ÷ 3 = 1,520. 0.08x + 0.12(15,000 − x) = 1,520 → 1,800 − 0.04x = 1,520 → x = 7,000 at 8%, so ₹8,000 at 12%. ₹7,000 is the part at 8%.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-simple-interest-33", "question": "The simple interest on a sum for 4 years is ₹1,600. At a rate 2 percentage points higher, the interest on the same sum for 3 years is ₹1,500. What is the sum?", "options": ["₹4,000", "₹5,000", "₹6,000", "₹2,500"], "answer": 1, "explanation": "4PR/100 = 1,600 → PR = 40,000. 3P(R + 2)/100 = 1,500 → PR + 2P = 50,000 → 2P = 10,000 → P = ₹5,000 (and R = 8%).", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-simple-interest-34", "question": "The simple interest on a sum for 3 years equals 3/8 of the amount at the end of those 3 years. What is the rate of interest per annum?", "options": ["20%", "12.5%", "15%", "25%"], "answer": 0, "explanation": "SI = (3/8)(P + SI) → (5/8)SI = (3/8)P → SI = 0.6P in 3 years. Rate = 60/3 = 20%. 12.5% treats 3/8 as a fraction of the principal.", "difficulty": "hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-simple-interest-35", "question": "A borrows ₹8,000 from B at 10% per annum simple interest. He lends half of it to C at 12% and the other half to D at 15% per annum simple interest. What is A's net gain after 2 years?", "options": ["₹2,160", "₹280", "₹720", "₹560"], "answer": 3, "explanation": "A pays 8,000 × 10% × 2 = 1,600. He earns 4,000 × 12% × 2 = 960 and 4,000 × 15% × 2 = 1,200, total 2,160. Net gain = 2,160 − 1,600 = ₹560. ₹2,160 forgets the interest A pays.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-simple-interest-36", "question": "₹14,000 is divided into two parts. One is lent at 10% for 3 years and the other at 8% for 5 years, both at simple interest, and the two interests are equal. What is the total interest received?", "options": ["₹2,400", "₹4,200", "₹4,800", "₹5,600"], "answer": 2, "explanation": "x × 10 × 3 = y × 8 × 5 → 30x = 40y → x : y = 4 : 3, so x = 8,000 and y = 6,000. Each interest = 8,000 × 30% = 2,400; total ₹4,800. ₹2,400 is just one of them.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-simple-interest-37", "question": "A sum doubles itself in 12 years at simple interest. In how many years will it become 2.5 times itself at a rate 25% higher than the original rate?", "options": ["18 years", "14.4 years", "15 years", "12 years"], "answer": 1, "explanation": "Doubling in 12 years → rate = 100/12 = 8⅓%. The new rate = 1.25 × 8⅓ = 10.4167% (= 125/12 %). To gain 150% of P: time = 150 ÷ (125/12) = 14.4 years. 18 years keeps the old rate.", "difficulty": "very-hard", "source": "SSC CGL Tier-2"},
  {"id": "quant-simple-interest-38", "question": "How many of the following statements about simple interest are correct? 1. At 8% per annum a sum doubles in 12 years. 2. SI on ₹x for 2 years at r% equals SI on ₹x for r years at 2%. 3. If both principal and rate are doubled, the SI for the same time becomes 4 times. 4. The amount grows by the same sum every year.", "options": ["Only three", "Only two", "All four", "Only one"], "answer": 0, "explanation": "1: doubling at 8% needs 100/8 = 12.5 years ✗. 2: x·2·r/100 = x·r·2/100 ✓. 3: SI ∝ P × R, so 2 × 2 = 4 times ✓. 4: SI is constant each year ✓. Three are correct.", "difficulty": "very-hard", "source": "SSC CGL"},
  {"id": "quant-simple-interest-39", "question": "What is the simple interest on ₹4,800 at 6.25% per annum for 2 years?", "options": ["₹625", "₹600", "₹560", "₹480"], "answer": 1, "explanation": "SI = 4,800 × 6.25 × 2/100 = ₹600.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-simple-interest-40", "question": "At what rate of simple interest per annum does ₹2,000 earn ₹480 in 3 years?", "options": ["7.5%", "8%", "6%", "9%"], "answer": 1, "explanation": "R = SI × 100/(P × T) = 48,000/6,000 = 8%.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-simple-interest-41", "question": "What is the simple interest on ₹10,000 at 1% per month for 1 year?", "options": ["₹120", "₹1,000", "₹1,200", "₹100"], "answer": 2, "explanation": "1% per month is 12% per annum, so SI = 10,000 × 12/100 = ₹1,200. ₹100 is the interest for one month only.", "difficulty": "easy", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-simple-interest-42", "question": "In how many years will the simple interest on a sum be 3/5 of the sum at 12% per annum?", "options": ["4 years", "5 years", "6 years", "7.2 years"], "answer": 1, "explanation": "SI/P = RT/100: 3/5 = 12T/100, so T = 60/12 = 5 years.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-43", "question": "What is the ratio of the simple interest on a sum at 4% per annum for 6 years to that on the same sum at 6% per annum for 5 years?", "options": ["5 : 4", "2 : 3", "3 : 4", "4 : 5"], "answer": 3, "explanation": "SI ∝ R × T: 4 × 6 = 24 and 6 × 5 = 30, so the ratio is 24 : 30 = 4 : 5.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-44", "question": "The simple interest on a sum for 5 years at 8% per annum is ₹2,400 less than the sum itself. What is the sum?", "options": ["₹6,000", "₹3,000", "₹4,000", "₹5,000"], "answer": 2, "explanation": "SI = 40% of P, so P − 0.4P = 0.6P = 2,400 and P = ₹4,000. ₹6,000 sets the SI itself equal to ₹2,400.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-45", "question": "What is the simple interest on ₹7,200 at 6 2/3% per annum for 9 months?", "options": ["₹480", "₹360", "₹324", "₹400"], "answer": 1, "explanation": "SI = 7,200 × (20/3)/100 × 9/12 = 7,200 × 1/15 × 3/4 = ₹360. ₹480 uses a full year.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-46", "question": "The simple interest on ₹1,600 at r% per annum for 4 years equals the simple interest on ₹2,400 at (r − 2)% per annum for 3 years. What is r?", "options": ["12", "16", "18", "20"], "answer": 2, "explanation": "1,600 × r × 4 = 2,400 × (r − 2) × 3 gives 6,400r = 7,200r − 14,400, so r = 18. Check: both interests are ₹1,152.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-47", "question": "A sum doubles itself in 6 years at simple interest. At the same rate, what will ₹2,500 amount to in 9 years?", "options": ["₹7,500", "₹3,750", "₹5,000", "₹6,250"], "answer": 3, "explanation": "Doubling in 6 years means 100% interest in 6 years, so 9 years give 150%: SI = ₹3,750 and amount = ₹6,250. ₹3,750 is only the interest.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-48", "question": "A person deposits ₹500 at the beginning of every month for 12 months in a recurring deposit paying 6% per annum simple interest. How much interest does he earn at the end of the year?", "options": ["₹180", "₹195", "₹165", "₹360"], "answer": 1, "explanation": "The deposits earn interest for 12, 11, …, 1 months: 78 month-units in all. Interest = 500 × 78 × 6/(100 × 12) = ₹195. ₹360 wrongly gives all ₹6,000 a full year; ₹165 assumes end-of-month deposits.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-49", "question": "A bank lends ₹50,000 at 10% per annum simple interest for 2 years but deducts a 4% processing fee from the loan when it is paid out. What is the effective annual rate of interest for the borrower?", "options": ["12%", "10.4%", "12.5%", "14%"], "answer": 2, "explanation": "The borrower receives ₹48,000 but pays interest of ₹10,000 plus the ₹2,000 fee, a cost of ₹12,000 over 2 years. Effective rate = 12,000 × 100/(48,000 × 2) = 12.5%. 12% divides by ₹50,000.", "difficulty": "hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-50", "question": "A sum amounts to ₹2,240 in 2 years at 6% per annum simple interest. In how many years will it amount to ₹2,600 at the same rate?", "options": ["5 years", "6 years", "4.5 years", "5.5 years"], "answer": 0, "explanation": "P × 1.12 = 2,240 gives P = ₹2,000 and yearly interest ₹120. To earn ₹600 takes 600/120 = 5 years.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-51", "question": "At simple interest a sum becomes 7/5 of itself in 5 years. In how many years will it double at the same rate?", "options": ["12.5 years", "12 years", "15 years", "10 years"], "answer": 0, "explanation": "Interest of 2/5 in 5 years means R = 40/5 = 8% per annum; doubling needs 100% interest, i.e. 100/8 = 12.5 years.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "quant-simple-interest-52", "question": "At simple interest, the amounts of a sum after 3 years and after 5 years are in the ratio 13 : 15. What is the rate of interest per annum?", "options": ["8%", "12.5%", "12%", "10%"], "answer": 3, "explanation": "(100 + 3R)/(100 + 5R) = 13/15 gives 1,500 + 45R = 1,300 + 65R, so R = 10%. Check: 130 : 150 = 13 : 15.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-53", "question": "₹x lent at 8% per annum simple interest for 5 years amounts to the same as ₹y lent at 10% per annum for 3 years. What is x : y?", "options": ["3 : 4", "4 : 3", "14 : 13", "13 : 14"], "answer": 3, "explanation": "1.4x = 1.3y, so x : y = 1.3 : 1.4 = 13 : 14. Equating only the interests (0.4x = 0.3y) gives 3 : 4.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-54", "question": "₹3,900 is divided into two parts so that the amount of the first part after 2 years equals the amount of the second part after 4 years, both at 10% per annum simple interest. What is the second part?", "options": ["₹1,700", "₹1,800", "₹1,950", "₹2,100"], "answer": 1, "explanation": "1.2A = 1.4B, so A : B = 7 : 6 and B = 6/13 × 3,900 = ₹1,800. Check: 2,100 × 1.2 = 1,800 × 1.4 = ₹2,520.", "difficulty": "hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-55", "question": "A car loan of ₹1,44,000 is given at a flat 10% per annum simple interest for 2 years, repaid in 24 equal monthly instalments. What is each instalment?", "options": ["₹6,000", "₹7,200", "₹6,600", "₹7,440"], "answer": 1, "explanation": "Interest = 1,44,000 × 10% × 2 = ₹28,800, so the total repayable is ₹1,72,800 and each instalment is 1,72,800 ÷ 24 = ₹7,200. ₹6,000 repays only the principal.", "difficulty": "hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-simple-interest-56", "question": "A bank pays 8% per annum simple interest on a 3-year deposit but deducts 10% tax at source on the interest. What does a depositor of ₹50,000 receive at maturity?", "options": ["₹60,800", "₹62,000", "₹61,000", "₹60,000"], "answer": 0, "explanation": "Interest = 50,000 × 0.08 × 3 = ₹12,000; tax = ₹1,200, so he receives 50,000 + 10,800 = ₹60,800. ₹62,000 ignores the tax.", "difficulty": "hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-simple-interest-57", "question": "How many of the following statements about simple interest are correct?\n1. If the rate is halved and the time doubled, the interest is unchanged.\n2. At r% per annum a sum doubles in 100/r years.\n3. The SI on ₹P for 2 years at 5% equals the SI on ₹2P for 1 year at 5%.\n4. If a sum triples in 10 years, it becomes 9 times itself in 30 years.", "options": ["Only one", "All four", "Only three", "Only two"], "answer": 2, "explanation": "1, 2 and 3 are true (SI ∝ P × R × T; 2P × 5 × 1 = P × 5 × 2). 4: tripling in 10 years means 20% a year, so 9 times (800% interest) takes 40 years, not 30.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-simple-interest-58", "question": "A man invests ₹40,000, partly in a bank at 8% and the rest in bonds at 12%, both at simple interest. After 3 years his total amount is ₹52,600. He then reinvests only the bond money (with its interest) at 10% simple interest for 2 more years. What does that reinvestment amount to?", "options": ["₹40,800", "₹41,600", "₹30,000", "₹39,600"], "answer": 0, "explanation": "0.24a + 0.36(40,000 − a) = 12,600 gives 0.12a = 1,800, so a = ₹15,000 and bonds = ₹25,000. Bonds amount to 25,000 × 1.36 = ₹34,000 after 3 years, and 34,000 × 1.2 = ₹40,800 after 2 more.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-59", "question": "The simple interest on a sum for 5 years is ₹1,500 more than that for 3 years, and the amount after 8 years is ₹16,000. What is the rate of interest per annum?", "options": ["7%", "6%", "7.5%", "8%"], "answer": 2, "explanation": "Two years' interest = ₹1,500, so one year's = ₹750. P = 16,000 − 8 × 750 = ₹10,000 and R = 750/10,000 × 100 = 7.5%.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-60", "question": "A loan of ₹1,260 is to be repaid in 3 equal annual instalments at 5% per annum simple interest, the first due one year from now. What is each instalment?", "options": ["₹420", "₹483", "₹441", "₹460"], "answer": 3, "explanation": "Value everything at the end of year 3: 1,260 × 1.15 = ₹1,449 must equal x(1.10) + x(1.05) + x = 3.15x, so x = ₹460. ₹483 just divides ₹1,449 by 3, ignoring that early instalments also earn interest.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-61", "question": "₹2,600 is divided into three parts A, B and C such that, at the same rate of simple interest, the interest on A for 2 years, on B for 3 years and on C for 4 years are all equal. What is C?", "options": ["₹1,200", "₹400", "₹800", "₹600"], "answer": 3, "explanation": "2A = 3B = 4C gives A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, so C = 3/13 × 2,600 = ₹600. ₹1,200 is A.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-62", "question": "A man lends ₹10,000, part at 5% and the rest at 7% per annum simple interest. Had he interchanged the two rates, he would have earned ₹80 more every year. How much did he lend at 5%?", "options": ["₹6,000", "₹4,000", "₹7,000", "₹3,000"], "answer": 2, "explanation": "Interchanging changes the yearly interest by 0.02(a − b) = 80, where a is the part at 5%, so a − b = 4,000 and a + b = 10,000, giving a = ₹7,000. Gaining by the swap means the larger part was at the lower rate.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-63", "question": "Ram lends ₹6,000 at 5% per annum and Shyam lends ₹4,500 at 10% per annum, both at simple interest, on the same day. After how many years will their amounts be equal?", "options": ["15 years", "12 years", "8 years", "10 years"], "answer": 3, "explanation": "Ram's amount grows by ₹300 a year and Shyam's by ₹450. 6,000 + 300t = 4,500 + 450t gives 150t = 1,500, so t = 10 years.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO"},
  {"id": "quant-simple-interest-64", "question": "Assertion (A): On ₹1,000 at 10% per annum simple interest, the interest earned in the 5th year alone is ₹100.\nReason (R): Under simple interest, interest is always calculated on the original principal.", "options": ["A is false but R is true", "Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false"], "answer": 1, "explanation": "Since interest is always on the original ₹1,000 (R), each year's interest, including the 5th, is ₹100 (A). Under compound interest the 5th-year interest would be higher.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-simple-interest-65", "question": "The simple interest on a sum for 6 years is ₹2,000 less than the sum, and the simple interest for 12 years is ₹1,000 more than the sum. What is the sum?", "options": ["₹5,000", "₹5,500", "₹6,000", "₹4,500"], "answer": 0, "explanation": "SI(12) − SI(6) = 6 years' interest = (P + 1,000) − (P − 2,000) = ₹3,000. So SI(6) = ₹3,000 and P = 3,000 + 2,000 = ₹5,000 (rate 10%).", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id": "quant-simple-interest-66", "question": "The simple interest on ₹x at r% per annum for t years is ₹576. The simple interest on ₹2x at (r/2)% per annum for (t + 4) years is ₹960. What is t?", "options": ["6 years", "8 years", "5 years", "4 years"], "answer": 0, "explanation": "2x × r/2 = xr, so the interests are in the ratio of the times: (t + 4)/t = 960/576 = 5/3, giving 3t + 12 = 5t and t = 6.", "difficulty": "very-hard", "source": "SSC CGL Tier 2 · CDS"},
  {"id": "quant-simple-interest-67", "question": "A phone costs ₹30,000 in cash, or ₹6,000 down plus 12 monthly instalments of ₹2,200. What flat rate of simple interest per annum is charged under the instalment plan?", "options": ["10%", "8%", "9.09%", "12%"], "answer": 0, "explanation": "Amount financed = ₹24,000; total repaid = 12 × 2,200 = ₹26,400, so interest = ₹2,400 for 1 year: flat rate = 2,400/24,000 = 10%. 9.09% divides by ₹26,400 instead of the amount financed.", "difficulty": "very-hard", "source": "RRB NTPC · SSC CGL"},
  {"id": "quant-simple-interest-68", "question": "₹25,300 is divided among A, B and C so that their amounts after 2, 3 and 4 years respectively, at 10% per annum simple interest, are equal. What is C's share?", "options": ["₹7,800", "₹7,200", "₹9,100", "₹8,400"], "answer": 0, "explanation": "1.2A = 1.3B = 1.4C, so A : B : C = 1/12 : 1/13 : 1/14 = 91 : 84 : 78 (sum 253). C = 78/253 × 25,300 = ₹7,800. Check: 9,100 × 1.2 = 8,400 × 1.3 = 7,800 × 1.4 = ₹10,920.", "difficulty": "very-hard", "source": "IBPS PO Mains · SBI PO Mains"},
  {"id":"quant-simple-interest-69","question":"What is the simple interest on ₹18,000 at 9% per annum for 2½ years?","options":["₹3,240","₹4,050","₹4,500","₹4,860"],"answer":1,"explanation":"SI = 18,000 × 9 × 2.5/100 = ₹4,050. Using 2 years instead of 2.5 gives ₹3,240.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-simple-interest-70","question":"What principal will earn ₹1,350 as simple interest in 5 years at 4.5% per annum?","options":["₹6,000","₹6,750","₹5,400","₹3,000"],"answer":0,"explanation":"P = SI × 100/(R × T) = 1,350 × 100/22.5 = ₹6,000.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-simple-interest-71","question":"₹6,400 earns ₹1,152 as simple interest in 3 years. What is the rate per annum?","options":["18%","5.5%","6.5%","6%"],"answer":3,"explanation":"R = 1,152 × 100/(6,400 × 3) = 6%. 18% is the total interest for all three years.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"quant-simple-interest-72","question":"In how many years will ₹12,500 earn ₹3,750 as simple interest at 6% per annum?","options":["4 years","6 years","5 years","3 years"],"answer":2,"explanation":"T = 3,750 × 100/(12,500 × 6) = 5 years. Interest is 30% of the principal, and 30 ÷ 6 = 5.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-simple-interest-73","question":"A fixed deposit of ₹3 lakh earns 7.25% simple interest per annum. How much interest does it earn in one year?","options":["₹2,175","₹21,500","₹21,750","₹22,500"],"answer":2,"explanation":"7.25% of 3,00,000 = 3 × 7,250 = ₹21,750.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-simple-interest-74","question":"A village moneylender charges interest at 'one paisa per rupee per month'. What is the annual rate of simple interest?","options":["1%","12%","10%","6%"],"answer":1,"explanation":"1 paisa per rupee = 1% per month, so the annual rate is 12%.","difficulty":"easy","source":"SSC CHSL · State PSC"},
  {"id":"quant-simple-interest-75","question":"A loan carries interest of ₹1.50 per hundred rupees per month. What is the annual rate of simple interest?","options":["18%","15%","1.5%","12%"],"answer":0,"explanation":"₹1.50 per ₹100 per month = 1.5% per month = 18% per annum.","difficulty":"easy","source":"RRB NTPC · SSC CHSL"},
  {"id":"quant-simple-interest-76","question":"What is the simple interest on ₹73,000 at 10% per annum for 146 days (take 365 days in a year)?","options":["₹2,880","₹3,650","₹2,190","₹2,920"],"answer":3,"explanation":"146/365 = 0.4 year. SI = 73,000 × 10% × 0.4 = ₹2,920.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-simple-interest-77","question":"When the rate of interest falls from 9% to 7.5% per annum, a man's yearly simple interest income falls by ₹540. What is his capital?","options":["₹6,000","₹7,200","₹40,000","₹36,000"],"answer":3,"explanation":"A fall of 1.5% of the capital = ₹540, so the capital = 540 × 100/1.5 = ₹36,000.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-simple-interest-78","question":"The ratio of a principal to the simple interest on it for 8 years is 5 : 2. What is the rate per annum?","options":["2.5%","4%","5%","8%"],"answer":2,"explanation":"SI is 2/5 = 40% of the principal over 8 years, so R = 40/8 = 5%.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-simple-interest-79","question":"A bank pays 7% per annum simple interest on 3-year deposits and 0.5 percentage points extra to senior citizens. How much more does a senior citizen earn than others on ₹2,40,000 over 3 years?","options":["₹1,200","₹3,600","₹7,200","₹3,000"],"answer":1,"explanation":"Extra = 0.5% × 2,40,000 × 3 = ₹3,600. ₹1,200 is the extra for one year only.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-simple-interest-80","question":"What is the simple interest on ₹40,000 at 1.5% per month for 7 months?","options":["₹4,200","₹3,500","₹6,000","₹4,500"],"answer":0,"explanation":"Monthly interest = 1.5% of 40,000 = ₹600. For 7 months: ₹4,200.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-simple-interest-81","question":"The simple interest on a sum for 2 years at 8% per annum is ₹1,920. What is the simple interest on the same sum for 3 years at 10% per annum?","options":["₹3,600","₹2,880","₹3,000","₹4,000"],"answer":0,"explanation":"2 × 8 = 16% of the sum is ₹1,920, so 1% = ₹120. 3 × 10 = 30% gives ₹3,600.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-82","question":"A gold loan of ₹1,20,000 is taken at 1% per month simple interest and repaid with interest after 10 months. How much is repaid?","options":["₹1,21,200","₹1,34,400","₹1,30,000","₹1,32,000"],"answer":3,"explanation":"Interest = 1% × 10 months = 10% of the loan = ₹12,000. Repayment = ₹1,32,000.","difficulty":"moderate","source":"IBPS Clerk · RRB Clerk"},
  {"id":"quant-simple-interest-83","question":"A farmer borrows ₹3 lakh on a crop loan at 7% simple interest. For prompt repayment he gets an interest subvention of 3 percentage points. If he repays promptly after one year, how much interest does he save?","options":["₹12,000","₹21,000","₹9,000","₹6,300"],"answer":2,"explanation":"The subvention cuts the rate from 7% to 4%. Saving = 3% of 3,00,000 = ₹9,000; he pays ₹12,000 instead of ₹21,000.","difficulty":"moderate","source":"IBPS RRB · NABARD"},
  {"id":"quant-simple-interest-84","question":"The simple interest on ₹2,000 rises by ₹40 when the period is extended by 4 months. What is the rate per annum?","options":["2%","6%","8%","5%"],"answer":1,"explanation":"₹40 is the interest for 4 months = 1/3 year: R = 40 × 100/(2,000 × 1/3) = 6%.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-85","question":"A deposit pays simple interest of 9% per annum, credited every quarter. If the quarterly interest is ₹1,800, how much is deposited?","options":["₹20,000","₹80,000","₹60,000","₹72,000"],"answer":1,"explanation":"Yearly interest = 4 × 1,800 = ₹7,200 = 9% of the deposit. Deposit = ₹80,000.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-simple-interest-86","question":"A post office monthly income scheme pays 7.4% per annum simple interest, paid out every month. What is the monthly income on a deposit of ₹9 lakh?","options":["₹5,550","₹6,660","₹5,400","₹66,600"],"answer":0,"explanation":"Yearly interest = 7.4% of 9,00,000 = ₹66,600. Monthly = 66,600 ÷ 12 = ₹5,550.","difficulty":"moderate","source":"IBPS Clerk · RRB NTPC"},
  {"id":"quant-simple-interest-87","question":"What is the present worth of ₹11,520 due 2 years hence at 10% per annum simple interest?","options":["₹9,216","₹10,080","₹9,520","₹9,600"],"answer":3,"explanation":"Present worth P grows to P × 1.2 in 2 years, so P = 11,520 ÷ 1.2 = ₹9,600. Subtracting 20% of 11,520 (₹9,216) is the trap.","difficulty":"moderate","source":"SSC CGL · State PSC"},
  {"id":"quant-simple-interest-88","question":"₹400 amounts to ₹480 in 4 years at simple interest. What will ₹600 amount to in 5 years at a rate 1 percentage point higher?","options":["₹750","₹720","₹780","₹810"],"answer":2,"explanation":"Rate = 80 × 100/(400 × 4) = 5%, so the new rate is 6%. ₹600 for 5 years at 6% earns 30%, giving ₹780.","difficulty":"moderate","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-simple-interest-89","question":"In how many years will the simple interest on ₹3,600 at 7% per annum equal the simple interest on ₹4,200 at 9% per annum for 4 years?","options":["5 years","7 years","6 years","4.5 years"],"answer":2,"explanation":"Target = 4,200 × 9% × 4 = ₹1,512. Yearly interest on 3,600 at 7% = ₹252. Time = 1,512 ÷ 252 = 6 years.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-simple-interest-90","question":"A trader borrows ₹1 lakh at '2 paise per rupee per month' simple interest. How much interest does he owe after 18 months?","options":["₹3,600","₹36,000","₹24,000","₹18,000"],"answer":1,"explanation":"2 paise per rupee per month = 2% per month. For 18 months: 36% of 1,00,000 = ₹36,000.","difficulty":"moderate","source":"SSC CHSL · State PSC"},
  {"id":"quant-simple-interest-91","question":"Repaying a loan with 9% simple interest after 4 years costs ₹1,620 more than repaying it after 2 years. What is the loan amount?","options":["₹9,000","₹4,500","₹18,000","₹13,500"],"answer":0,"explanation":"The extra cost is 2 years' interest = 18% of the loan = ₹1,620. Loan = ₹9,000.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-simple-interest-92","question":"₹20,000 is lent at r% per annum simple interest for the first 3 years and at (r + 2)% for the next 2 years. If the total interest is ₹9,800, what is r?","options":["7","8","10","9"],"answer":3,"explanation":"Interest = 20,000 × [3r + 2(r + 2)]/100 = 200(5r + 4) = 9,800. So 5r + 4 = 49 and r = 9.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-93","question":"Two equal sums are lent at 8% and 6% per annum simple interest. The second is lent for 3 years longer than the first, and both earn the same interest. For how many years is the second sum lent?","options":["9","15","10","12"],"answer":3,"explanation":"8t = 6(t + 3) gives 2t = 18, so t = 9 and the second sum is lent for 12 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-94","question":"The simple interest on a sum for 3 years at r% is ₹4,500, and for 4 years at (r + 3)% it is ₹8,400. What is the sum?","options":["₹15,000","₹25,000","₹20,000","₹18,000"],"answer":2,"explanation":"P × r = 1,50,000 and P × (r + 3) = 2,10,000. Subtracting, 3P = 60,000, so P = ₹20,000 (and r = 7.5).","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-95","question":"Mohan deposits ₹1,000 at the start of each year for 4 years in a scheme paying 10% simple interest. How much does he get at the end of the fourth year?","options":["₹4,400","₹5,000","₹4,600","₹5,400"],"answer":1,"explanation":"The deposits earn interest for 4, 3, 2 and 1 years: 1,400 + 1,300 + 1,200 + 1,100 = ₹5,000.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-simple-interest-96","question":"A man borrows ₹5,000 at 10% simple interest, charged only on the principal outstanding. At the end of the first year he pays that year's interest plus ₹2,000 of principal. How much must he pay at the end of the second year to clear the loan?","options":["₹3,300","₹3,850","₹3,500","₹3,000"],"answer":0,"explanation":"After year 1 the outstanding principal is ₹3,000. Year 2 interest = ₹300, so he pays ₹3,300.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-97","question":"A sum amounts to ₹13,800 in 4 years at r% simple interest and to ₹16,200 in 4 years at (r + 5)%. What is r?","options":["3.75","5","4.5","3.5"],"answer":0,"explanation":"5% extra for 4 years = 20% of P = ₹2,400, so P = ₹12,000. Interest at r% = ₹1,800, giving r = 1,800 × 100/(12,000 × 4) = 3.75.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-98","question":"Bank A pays 8.5% simple interest on a 3-year deposit. Bank B pays 8% but adds a ₹600 bonus at maturity. For what deposit do the two banks pay the same?","options":["₹20,000","₹1,20,000","₹60,000","₹40,000"],"answer":3,"explanation":"Bank A's extra = 0.5% × 3 years = 1.5% of the deposit. 1.5% = ₹600 gives ₹40,000. Below this, Bank B is better.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-99","question":"A sum earns simple interest at r% in the first year, 2r% in the second year and 3r% in the third year. If the total interest is 24% of the sum, what is r?","options":["8","6","4","3"],"answer":2,"explanation":"Total rate = r + 2r + 3r = 6r = 24, so r = 4.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-simple-interest-100","question":"A man lends ₹x to A at 10% for 3 years and ₹(x + 5,000) to B at 8% for 2 years, both at simple interest. If his total interest is ₹4,480, what is x?","options":["₹9,000","₹8,000","₹7,500","₹6,000"],"answer":1,"explanation":"0.3x + 0.16(x + 5,000) = 4,480 gives 0.46x + 800 = 4,480, so x = ₹8,000.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-simple-interest-101","question":"₹6,000 is lent at 12% and ₹7,500 at 8% per annum simple interest, starting on the same day. After how many years will the two amounts be equal?","options":["10 years","12.5 years","15 years","12 years"],"answer":1,"explanation":"The first grows by ₹720 a year and the second by ₹600, so the gap of ₹1,500 closes at ₹120 a year: 1,500 ÷ 120 = 12.5 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-102","question":"A sum earns a certain simple interest in t years at 10% per annum. At 8% per annum it takes one year more to earn the same interest. What is t?","options":["4","5","3","8"],"answer":0,"explanation":"Same interest means the same rate × time: 10t = 8(t + 1), so t = 4.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-simple-interest-103","question":"A two-wheeler costs ₹20,000 in cash, or ₹5,000 down and ₹15,900 after 6 months. What annual rate of simple interest is being charged?","options":["6%","9%","10.6%","12%"],"answer":3,"explanation":"The amount financed is ₹15,000 and the interest is ₹900 for half a year. Rate = 900 × 100/(15,000 × 0.5) = 12%.","difficulty":"hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-104","question":"What is the true discount on ₹5,300 due 9 months hence at 8% per annum simple interest?","options":["₹318","₹280","₹300","₹312"],"answer":2,"explanation":"Interest for 9 months at 8% = 6%, so the present worth = 5,300 ÷ 1.06 = ₹5,000 and the true discount = ₹300. 6% of 5,300 (₹318) is the trap.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"quant-simple-interest-105","question":"A cooperative bank pays 8% simple interest on the first ₹1 lakh of a deposit and 9% on the amount above ₹1 lakh. A 2-year deposit earns ₹25,000 in interest. How much was deposited?","options":["₹1,38,889","₹1,40,000","₹1,50,000","₹1,56,250"],"answer":2,"explanation":"The first lakh earns 16% over 2 years = ₹16,000. The remaining ₹9,000 is 18% of the excess, so the excess = ₹50,000 and the deposit = ₹1,50,000.","difficulty":"hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-106","question":"A scheme pays 4% simple interest in the first year, and the rate goes up by 1 percentage point every year after that. After how many years will the total interest equal 49% of the principal?","options":["6","7","8","9"],"answer":1,"explanation":"Add the rates: 4 + 5 + 6 + 7 + 8 + 9 + 10 = 49 after 7 years.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-107","question":"If both the rate and the time of a simple-interest loan are increased by 20%, the interest goes up by ₹1,320. What was the original interest?","options":["₹3,000","₹3,300","₹6,600","₹2,750"],"answer":0,"explanation":"SI ∝ rate × time, so it becomes 1.2 × 1.2 = 1.44 times, a 44% rise. 44% = ₹1,320 gives ₹3,000. A 40% rise would give ₹3,300.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-108","question":"The principal of a loan is increased by 25%, the rate of simple interest is cut by 20% and the time is extended by 10%. By what percent does the interest change?","options":["15% increase","No change","5% increase","10% increase"],"answer":3,"explanation":"SI ∝ P × R × T: 1.25 × 0.8 × 1.1 = 1.1, a 10% increase. Note 1.25 × 0.8 = 1 exactly.","difficulty":"hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-simple-interest-109","question":"A credit card company charges 18% per annum simple interest on unpaid dues. What is the interest on ₹24,000 left unpaid for 73 days (365-day year)?","options":["₹4,320","₹720","₹1,080","₹864"],"answer":3,"explanation":"73 days = 73/365 = 1/5 year. Interest = 24,000 × 18% × 1/5 = ₹864.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-simple-interest-110","question":"A tax of ₹50,000 is paid 7 months late. The law charges simple interest at 1% per month on the tax plus a flat penalty of ₹5,000. How much is paid in all?","options":["₹55,000","₹59,200","₹58,500","₹53,500"],"answer":2,"explanation":"Interest = 1% × 7 months = 7% of 50,000 = ₹3,500. Total = 50,000 + 3,500 + 5,000 = ₹58,500.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"quant-simple-interest-111","question":"The simple interest on a sum at 8% per annum for 5 years exceeds the simple interest on it at 6% per annum for 6 years by ₹240. What is the sum?","options":["₹4,000","₹6,000","₹12,000","₹2,400"],"answer":1,"explanation":"8 × 5 = 40% and 6 × 6 = 36%. The 4% difference = ₹240, so the sum = ₹6,000.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-simple-interest-112","question":"Of ₹50,000, ₹20,000 is invested at 6%, ₹18,000 at 8% and the rest at 10% simple interest. What is the average rate of interest earned?","options":["7.68%","8%","7.6%","7.84%"],"answer":0,"explanation":"Yearly interest = 1,200 + 1,440 + 1,200 = ₹3,840. Average rate = 3,840/50,000 = 7.68%. The plain average of the rates (8%) ignores the amounts.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-simple-interest-113","question":"A sum is lent at r% simple interest for 4 years and then at (r + 2)% for 3 more years. If the total interest is 41% of the sum, what is r?","options":["5","6","4","5.5"],"answer":0,"explanation":"4r + 3(r + 2) = 41 gives 7r = 35, so r = 5.","difficulty":"hard","source":"SSC CHSL · SSC CGL"},
  {"id":"quant-simple-interest-114","question":"A bank deducts 10% tax at source only when a depositor's interest in a year exceeds ₹40,000. Asha's deposit of ₹5 lakh earns 7% simple interest a year. How much interest does she receive each year?","options":["₹31,500","₹34,500","₹32,000","₹35,000"],"answer":3,"explanation":"Yearly interest = 7% of 5,00,000 = ₹35,000, which is below the ₹40,000 limit, so no tax is deducted. She receives the full ₹35,000.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk"},
  {"id":"quant-simple-interest-115","question":"A lender gives a one-year loan at 12% simple interest but deducts the interest in advance from the amount paid out. What is the effective annual rate for the borrower?","options":["12%","13%","13.64%","10.71%"],"answer":2,"explanation":"On ₹100 of loan the borrower gets only ₹88 but repays ₹100. Effective rate = 12/88 = 13.64%.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-116","question":"The simple interest on a sum is 24% of the sum. If the rate were 2 percentage points lower and the time 2 years longer, the interest would be the same. What is the rate?","options":["4%","6%","8%","3%"],"answer":1,"explanation":"rt = 24 and (r − 2)(t + 2) = 24 give 2r − 2t = 4, so r = t + 2. Then r(r − 2) = 24, so r = 6 (t = 4).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-simple-interest-117","question":"Three sums A, B and C are lent at simple interest: A for 2 years at 6%, B for 3 years at 5% and C for 4 years at 4.5%. If all three earn equal interest, what is A : B : C?","options":["10 : 12 : 15","15 : 12 : 10","12 : 15 : 18","6 : 5 : 4"],"answer":1,"explanation":"Interest rates for the periods are 12%, 15% and 18%. Equal interest means 12A = 15B = 18C, so A : B : C = 1/12 : 1/15 : 1/18 = 15 : 12 : 10.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-118","question":"A loan is taken at 12% simple interest. After 2 years, half the amount then due is paid. The rest is treated as a fresh loan at 12% simple interest and cleared a year later with a payment of ₹34,720. What was the original loan?","options":["₹50,000","₹56,000","₹48,000","₹62,000"],"answer":0,"explanation":"After 2 years the due is 1.24P; half of it, 0.62P, is carried forward and becomes 0.62P × 1.12 = 0.6944P. So P = 34,720 ÷ 0.6944 = ₹50,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-119","question":"At simple interest a sum doubles in n years and triples in (n + 10) years. What is n?","options":["20","5","15","10"],"answer":3,"explanation":"Doubling means interest = P in n years; tripling means interest = 2P in n + 10 years. So n + 10 = 2n and n = 10.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-simple-interest-120","question":"A student takes an education loan of ₹5 lakh at 9% simple interest. Interest accrues during the 4-year course; then the loan plus accrued interest becomes a fresh principal repaid with 9% simple interest over 5 years. What is the total interest paid?","options":["₹4,05,000","₹3,06,000","₹4,86,000","₹4,50,000"],"answer":2,"explanation":"Accrued interest = 5,00,000 × 36% = ₹1,80,000. New principal ₹6,80,000 earns 45% = ₹3,06,000. Total interest = 1,80,000 + 3,06,000 = ₹4,86,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-121","question":"A finance company lends ₹1,20,000 for one year at a 'flat' 10% interest, repaid in 12 equal monthly instalments. Taking interest on the average principal actually outstanding during the year, the true rate is approximately:","options":["10%","20%","18.5%","12%"],"answer":2,"explanation":"Principal outstanding falls from 1,20,000 to 10,000 in steps of 10,000, averaging ₹65,000. Interest ₹12,000 on ₹65,000 ≈ 18.5%, nearly double the flat rate.","difficulty":"very-hard","source":"IBPS PO Mains · RBI Grade B"},
  {"id":"quant-simple-interest-122","question":"Ram invests ₹P for 2 years at r% simple interest. Shyam invests ₹2P for 3 years at (r − 2)%. Shyam's interest is 1.5 times Ram's. What is r?","options":["6","4","8","3"],"answer":1,"explanation":"Shyam: 2P × 3 × (r − 2) = 6P(r − 2); Ram: 2Pr. So 6(r − 2) = 1.5 × 2r = 3r, giving r = 4.","difficulty":"very-hard","source":"SSC CGL · IBPS PO"},
  {"id":"quant-simple-interest-123","question":"₹20,000 is borrowed at 10% simple interest. ₹8,000 is repaid at the end of 2 years, and that payment is credited with simple interest at the same rate till settlement. How much must be paid at the end of 4 years to clear the loan?","options":["₹18,400","₹20,000","₹17,600","₹19,200"],"answer":0,"explanation":"The loan grows to 20,000 × 1.4 = ₹28,000. The payment grows to 8,000 × 1.2 = ₹9,600 by then. Balance = ₹18,400.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"quant-simple-interest-124","question":"₹P is lent at 5% and ₹(P + 1,000) at 4% simple interest, both for the same period. If both earn the same interest, what is P?","options":["₹5,000","₹3,000","₹4,500","₹4,000"],"answer":3,"explanation":"5P × t = 4(P + 1,000) × t; the time cancels, so P = 4,000 for any period.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-125","question":"The simple interest on ₹P at r% for t years is ₹1,800. What is the simple interest on ₹1.5P at (r/3)% for 2t years?","options":["₹2,700","₹1,200","₹3,600","₹1,800"],"answer":3,"explanation":"SI scales as P × R × T: 1.5 × 1/3 × 2 = 1. The interest is unchanged at ₹1,800.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-126","question":"The simple interest on ₹6,000 at x% per annum for x months is ₹320. What is x?","options":["6","12","8","10"],"answer":2,"explanation":"SI = 6,000 × x/100 × x/12 = 5x². So 5x² = 320, x² = 64 and x = 8.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS"},
  {"id":"quant-simple-interest-127","question":"A sum triples in 15 years at simple interest. After 10 years, what percentage of the amount is interest?","options":["66.67%","57.14%","133.33%","42.86%"],"answer":1,"explanation":"Interest of 200% in 15 years means 13⅓% a year, so in 10 years it is 133⅓% of P. Amount = 233⅓%. Share = 133⅓/233⅓ = 4/7 ≈ 57.14%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-simple-interest-128","question":"The simple interest on a sum for the 4th year alone is ₹480, and the amount after 6 years is ₹8,880. What is the rate per annum?","options":["8%","5.4%","10%","6%"],"answer":0,"explanation":"Simple interest is the same every year, so 6 years' interest = ₹2,880 and P = 8,880 − 2,880 = ₹6,000. Rate = 480/6,000 = 8%.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-129","question":"A deposit scheme pays 9% simple interest in the first year, and the rate falls by 0.5 percentage points each year after that. Over 4 years the interest is ₹9,900. What was the deposit?","options":["₹30,000","₹27,500","₹33,000","₹36,000"],"answer":0,"explanation":"Total rate = 9 + 8.5 + 8 + 7.5 = 33%. Deposit = 9,900 ÷ 0.33 = ₹30,000.","difficulty":"very-hard","source":"IBPS Clerk · SBI PO"},
  {"id":"quant-simple-interest-130","question":"Bank A pays 7% simple interest a year. Bank B pays 7.5% but charges a fee of ₹250 a year. Bank B gives more net interest only for deposits above:","options":["₹25,000","₹35,714","₹5,00,000","₹50,000"],"answer":3,"explanation":"Bank B's extra 0.5% must beat ₹250: 0.005 × P > 250 means P > ₹50,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-131","question":"A sum grows to 1.32 times itself in 4 years at simple interest. The rate is then raised by 2 percentage points. How many more years will it take for the amount to reach 1.8 times the original sum?","options":["6 years","4 years","4.8 years","5 years"],"answer":2,"explanation":"The rate is 32/4 = 8%, now 10%. The remaining 48% of P needs 48/10 = 4.8 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-132","question":"₹8,000 is lent at 5% simple interest for 3 years, and the whole amount is then lent at 10% simple interest for 2 more years. What is the final amount?","options":["₹11,040","₹10,800","₹11,200","₹10,400"],"answer":0,"explanation":"After 3 years: 8,000 × 1.15 = ₹9,200. Then 20% more: 9,200 × 1.2 = ₹11,040.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-133","question":"What is the simple interest on ₹4,500 for 146 days at 10% per annum (365-day year)?","options":["₹146","₹450","₹200","₹180"],"answer":3,"explanation":"146/365 = 2/5 year. SI = 4,500 × 10% × 2/5 = ₹180.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-simple-interest-134","question":"A sum doubles in 8 years at simple interest. After 6 years, what percentage of the amount is interest?","options":["75%","37.5%","42.86%","50%"],"answer":2,"explanation":"The rate is 12.5%, so 6 years give 75% of the sum. Amount = 175%, and 75/175 ≈ 42.86%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-simple-interest-135","question":"The simple interest on ₹x for 9 months at 8% equals the simple interest on ₹(x + 1,000) for 6 months at 10%. What is x?","options":["₹4,000","₹5,000","₹6,000","₹2,500"],"answer":1,"explanation":"9 months at 8% = 6%; 6 months at 10% = 5%. 6x = 5(x + 1,000) gives x = ₹5,000.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"quant-simple-interest-136","question":"A sum is lent at simple interest for 4 years. If the period were 6 months longer and the rate 1 percentage point lower, the interest would be the same. What is the rate?","options":["8%","9%","10%","4.5%"],"answer":1,"explanation":"4r = 4.5(r − 1) gives 0.5r = 4.5, so r = 9%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-simple-interest-137","question":"A invests ₹x at 9% and B invests ₹x at 6% simple interest. After 5 years A has earned ₹1,800 more than B. What is x?","options":["₹12,000","₹6,000","₹36,000","₹8,000"],"answer":0,"explanation":"The extra 3% a year for 5 years = 15% of x = ₹1,800, so x = ₹12,000.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-simple-interest-138","question":"The simple interest on ₹3,000 at r% for 4 years plus the simple interest on ₹2,000 at (r + 2)% for 3 years is ₹1,560. What is r?","options":["6","7","9","8"],"answer":3,"explanation":"120r + 60(r + 2) = 1,560 gives 180r = 1,440, so r = 8.","difficulty":"hard","source":"SSC CGL · IBPS Clerk"},
  {"id":"quant-simple-interest-139","question":"₹1 lakh earns 8% simple interest a year. Each year-end interest is moved at once to a second scheme paying 10% simple interest. What is the total value of both schemes at the end of 3 years?","options":["₹1,24,000","₹1,27,200","₹1,26,400","₹1,25,600"],"answer":2,"explanation":"The three ₹8,000 instalments earn 10% for 2, 1 and 0 years: 9,600 + 8,800 + 8,000 = ₹26,400. Add the ₹1,00,000 principal.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"quant-simple-interest-140","question":"₹2,500 earns ₹75 simple interest in 3 months. What is the annual rate?","options":["3%","9%","12%","10%"],"answer":2,"explanation":"Yearly interest = 75 × 4 = ₹300, which is 12% of ₹2,500.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id":"quant-simple-interest-141","question":"What is the simple interest on ₹25,000 at 6% per annum for 1 year 3 months?","options":["₹1,500","₹1,875","₹1,950","₹2,250"],"answer":1,"explanation":"1 year 3 months = 1.25 years. SI = 25,000 × 6% × 1.25 = ₹1,875.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk"},
  {"id":"quant-simple-interest-142","question":"The simple interest on a sum is one-fourth of the sum, and the rate per annum is four times the number of years. What is the rate?","options":["10%","5%","8%","12.5%"],"answer":0,"explanation":"r × t = 25 and r = 4t, so 4t² = 25, t = 2.5 years and r = 10%.","difficulty":"very-hard","source":"SSC CGL · SSC CPO"},
  {"id":"quant-simple-interest-143","question":"A moneylender charges 15% simple interest a year but counts any part of a month as a full month. How much interest does he charge on ₹10,000 borrowed for 2 months and 10 days?","options":["₹292","₹250","₹300","₹375"],"answer":3,"explanation":"2 months 10 days is charged as 3 months = 1/4 year. Interest = 10,000 × 15% × 1/4 = ₹375.","difficulty":"hard","source":"SSC CGL · State PSC"},
];

export default questions;
